/** Сторінки «Політика конфіденційності» й «Умови використання» (короткі тексти навчального проєкту). */
import { DISCLAIMER, CFG } from '../config.js';
import * as tg from '../tg.js';
import { money } from '../format.js';

const PAGES = {
  privacy: {
    title: 'Політика конфіденційності',
    body: [
      ['Що ми зберігаємо', 'Telegram id, ім\'я й необов\'язковий username, ознаку підтвердження особи та її час, час згоди з умовами, поїздки, платежі й журнал подій.'],
      ['Де це зберігається', 'У прототипі всі дані лишаються на вашому пристрої, у сховищі застосунку. Вони не передаються на сервер і не передаються операторам. У MVP дані зберігатиме серверна частина проєкту.'],
      ['Позиція', 'Позиція потрібна лише для показу транспорту поруч, і саму позицію користувача застосунок не записує. На пристрої лишаються округлений центр автопарку та положення імітованого транспорту, зокрема після поїздки: його ставимо поблизу місця завершення зі зсувом у десятки метрів і округленням.'],
      ['Підтвердження особи', 'Дія й BankID у прототипі імітуються, документи не збираються й не передаються.'],
      ['Видалення', 'Кнопка «Скинути демо-дані» у Профілі видаляє всі дані застосунку на пристрої.'],
      ['Карта', 'Плитки карти завантажує OpenStreetMap; його сервери бачать адресу вашого пристрою, як для будь-якого сайту.'],
    ],
  },
  terms: {
    title: 'Умови використання',
    body: [
      ['Статус', 'єМобільність є навчальним проєктом. Дані операторів імітовані, оплата й підтвердження особи вигадані. Проєкт не пов\'язаний з Bolt, Jet і Zelektra.'],
      ['Вік', `Командне припущення: користувачеві не менше 16 років.`],
      ['Розблокування', `Для розблокування потрібні згода з цими умовами, підтверджена особа та щонайменше ${money(CFG.MIN_BALANCE, { compact: true })} на балансі. Поки є борг, нова поїздка заблокована.`],
      ['Оплата', 'З гаманця списується тариф оператора: розблокування плюс ціна за хвилину, хвилини рахуються вгору, мінімум одна. Якщо коштів не вистачило, різниця стає боргом і гаситься першим поповненням.'],
      ['Відповідальність', 'У прототипі справжні транспорт, гроші й документи не використовуються, тож і відповідальності за них немає.'],
    ],
  },
};

export function mount(root, ctx, which) {
  const p = PAGES[which];
  root.innerHTML = `<div class="screen legal"><h1>${p.title}</h1>
    ${p.body.map(([h, t]) => `<h2 class="sec">${h}</h2><p>${t}</p>`).join('')}
    <p class="disclaimer">${DISCLAIMER}</p></div>`;
  tg.back.set(() => ctx.back(which === 'privacy' || which === 'terms' ? '#profile' : '#s1'));
  tg.main.hide();
  return () => {};
}
